@Override public int send(long fd,long buffer,int bufferLen){
  Assert.assertEquals(FD,fd);
  if (null != sentBytes) {
    return 0;
  }
  if (maxSendBytes <= 0) {
    return maxSendBytes;
  }
  int nSent=Math.min(bufferLen,maxSendBytes);
  sentBytes=new byte[nSent];
  try {
    for (int n=0; n < nSent; n++) {
      sentBytes[n]=Unsafe.getUnsafe().getByte(buffer + n);
    }
  } catch (RuntimeException e) {
    e.printStackTrace();
    return -1; // 返回错误码表示异常
  }
  return nSent;
}
